     "title": "Why Trump Can't Afford to Lose The Rare Earth Race",
     "url": "https://oilprice.com/Energy/Energy-General/Why-Trump-Cant-Afford-to-Lose-The-Rare-Earth-Race.html",
     "time": "10-23 10:00",
